@page "/courses"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService
@rendermode InteractiveServer

<PageTitle>Courses - University Course Catalog</PageTitle>

<div class="container">
    <h1>Course Catalog</h1>

    <div class="row mb-4">
        <div class="col-md-6">
            <input type="text" class="form-control" placeholder="Search by title, code, or instructor..."
                   @bind="searchTerm" @bind:event="oninput" />
        </div>
        <div class="col-md-4">
            <select class="form-select" @bind="selectedDepartmentId">
                <option value="0">All Departments</option>
                @foreach (var dept in departments)
                {
                    <option value="@dept.Id">@dept.Name</option>
                }
            </select>
        </div>
    </div>

    @if (filteredCourses.Any())
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead>
                    <tr>
                        <th>Code</th>
                        <th>Title</th>
                        <th>Department</th>
                        <th>Credits</th>
                        <th>Instructor</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var course in filteredCourses)
                    {
                        <tr>
                            <td>@course.CourseCode</td>
                            <td>@course.Title</td>
                            <td>@course.DepartmentName</td>
                            <td>@course.Credits</td>
                            <td>@course.InstructorName</td>
                            <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }
    else
    {
        <div class="alert alert-info">No courses match your search criteria.</div>
    }
</div>

@code {
    private List<Department> departments = new();
    private List<Course> filteredCourses = new();
    private string _searchTerm = string.Empty;
    private int _selectedDepartmentId;

    private string searchTerm
    {
        get => _searchTerm;
        set
        {
            _searchTerm = value;
            FilterCourses();
        }
    }

    private int selectedDepartmentId
    {
        get => _selectedDepartmentId;
        set
        {
            _selectedDepartmentId = value;
            FilterCourses();
        }
    }

    [SupplyParameterFromQuery]
    public int? departmentId { get; set; }

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        if (departmentId.HasValue)
        {
            _selectedDepartmentId = departmentId.Value;
        }
        FilterCourses();
    }

    private void FilterCourses()
    {
        filteredCourses = CatalogService.SearchCourses(
            string.IsNullOrWhiteSpace(_searchTerm) ? null : _searchTerm,
            _selectedDepartmentId > 0 ? _selectedDepartmentId : null);
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>Enroll - University Course Catalog</PageTitle>

<div class="container">
    <h1>Enrollment Request</h1>
    <p class="text-muted">Submit your enrollment request below. You will receive confirmation via your university email.</p>

    @if (submitted)
    {
        <div class="alert alert-success">
            <h4>Enrollment Request Submitted!</h4>
            <p>Thank you, <strong>@Model.StudentName</strong>. Your request to enroll in <strong>@selectedCourseName</strong> has been received.</p>
            <a href="/courses" class="btn btn-primary">Browse More Courses</a>
        </div>
    }
    else
    {
        <div class="row">
            <div class="col-lg-6">
                <EditForm Model="Model" FormName="enrollment" OnValidSubmit="HandleSubmit" method="post">
                    <DataAnnotationsValidator />
                    <ValidationSummary class="text-danger" />

                    <div class="mb-3">
                        <label for="studentName" class="form-label">Full Name</label>
                        <InputText id="studentName" class="form-control" @bind-Value="Model.StudentName" />
                        <ValidationMessage For="() => Model.StudentName" class="text-danger" />
                    </div>

                    <div class="mb-3">
                        <label for="studentId" class="form-label">Student ID</label>
                        <InputText id="studentId" class="form-control" @bind-Value="Model.StudentId" />
                        <ValidationMessage For="() => Model.StudentId" class="text-danger" />
                    </div>

                    <div class="mb-3">
                        <label for="courseId" class="form-label">Course</label>
                        <InputSelect id="courseId" class="form-select" @bind-Value="Model.CourseId">
                            <option value="0">-- Select a course --</option>
                            @foreach (var course in courses)
                            {
                                <option value="@course.Id">@course.CourseCode - @course.Title</option>
                            }
                        </InputSelect>
                        <ValidationMessage For="() => Model.CourseId" class="text-danger" />
                    </div>

                    <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
                    <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
                </EditForm>
            </div>
        </div>
    }
</div>

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? courseId { get; set; }

    private List<Course> courses = new();
    private bool submitted;
    private string selectedCourseName = string.Empty;

    protected override void OnInitialized()
    {
        courses = CatalogService.GetAllCourses();
        if (courseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = courseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var course = CatalogService.GetCourse(Model.CourseId);
        selectedCourseName = course is not null ? $"{course.CourseCode} - {course.Title}" : "Unknown";
        submitted = CatalogService.SubmitEnrollmentRequest(Model);
    }
}

